class Solution:
    def nextGreaterElements(self, nums: list[int]) -> list[int]:
        result = [-1] * len(nums)
        for i in range(len(nums)):
            for step in range(1, len(nums)):
                value = nums[(i + step) % len(nums)]
                if value > nums[i]:
                    result[i] = value
                    break
        return result
